// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract AlphaPonyServiceContract is ReentrancyGuard, Ownable {
    address public client;
    address public serviceProvider;
    uint256 public totalAmount;
    uint256 public deadline;
    string public serviceType;

    mapping(uint256 => uint256) public milestonePayments;
    uint256 public totalMilestones;
    uint256 public currentMilestone;

    enum Status { Pending, InProgress, Completed, Disputed }
    Status public contractStatus;

    event PaymentReceived(address from, uint256 amount);
    event MilestoneReleased(uint256 milestone, uint256 amount);
    event ContractCompleted(uint256 totalPaid);

    modifier onlyClient() {
        require(msg.sender == client, "Only client can call this function");
    }

    modifier onlyServiceProvider() {
        require(msg.sender == serviceProvider, "Only service provider can call this function");
    }

    constructor(
        address _client,
        address _serviceProvider,
        uint256 _totalAmount,
        uint256 _deadline,
        string memory _serviceType,
        uint256 _totalMilestones
    ) {
        client = _client;
        serviceProvider = _serviceProvider;
        totalAmount = _totalAmount;
        deadline = _deadline;
        serviceType = _serviceType;
        totalMilestones = _totalMilestones;
        contractStatus = Status.Pending;
        currentMilestone = 0;
    }

    receive() external payable nonReentrant {
        require(block.timestamp <= deadline, "Payment deadline has passed");
        require(contractStatus == Status.Pending, "Contract not in pending state");
        require(msg.value == totalAmount, "Incorrect payment amount");

        emit PaymentReceived(msg.sender, msg.value);
        contractStatus = Status.InProgress;
    }

    function releaseMilestone() external onlyServiceProvider nonReentrant {
        require(contractStatus == Status.InProgress, "Contract not in progress");
        require(currentMilestone < totalMilestones, "All milestones completed");

        uint256 milestoneAmount = milestonePayments[currentMilestone];
        require(address(this).balance >= milestoneAmount, "Insufficient contract balance");

        payable(serviceProvider).transfer(milestoneAmount);
        emit MilestoneReleased(currentMilestone, milestoneAmount);
        currentMilestone++;

        if (currentMilestone == totalMilestones) {
            contractStatus = Status.Completed;
            emit ContractCompleted(totalAmount);
        }
    }

    function setMilestonePayment(uint256 milestone, uint256 amount) external onlyOwner {
        require(milestone < totalMilestones, "Invalid milestone");
        milestonePayments[milestone] = amount;
    }

    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function getRemainingTime() external view returns (uint256) {
        if (block.timestamp >= deadline) return 0;
        return deadline - block.timestamp;
    }

    function dispute() external onlyClient {
        require(contractStatus == Status.InProgress, "Contract not in progress");
        contractStatus = Status.Disputed;
    }

    function resolveDispute(bool clientWins) external onlyOwner {
        require(contractStatus == Status.Disputed, "No active dispute");

        if (clientWins) {
            payable(client).transfer(address(this).balance);
        } else {
            payable(serviceProvider).transfer(address(this).balance);
        }

        contractStatus = Status.Completed;
    }
}
